    "k": "L",
    "de": "Man sollte meinen, Schauspieler Hendrik Höfgen wäre gegen unmoralische Angebote gefeit. Schließlich feierte er zur Zeit der Weimarer Republik große Erfolge in der Rolle des Mephisto. Der Mann müsste also wissen, wie schnell es gehen kann, dass man seine Seele verkauft. Als die Nazis die Macht ergreifen, stellt Höfgen seine Kunst ganz in den Dienst der neuen Herrscher. Und bald wird er zum Intendanten des Staatstheaters ernannt. Das Drama um Kunst und Politik entstand nach dem gleichnamigen Roman von Klaus Mann.",
    "summary": "فيلم درامي مقتبس عن رواية لكلاوس مان يتناول قصة الممثل هندريك هوفغن الذي يتخلى عن مبادئه الفنية والسياسية بعد صعود النازيين إلى السلطة ويتعاون معهم مقابل نيل الشهرة ومنصب مدير المسرح الحكومي."
