    "k": "L",
    "de": "Musiker gesucht Seit einem Jahr vermitteln wir „Musiktandems\" - Musiker suchen Musiker und geben sich gegenseitig Unterricht. Ob Instrument, Gesang, Komposition - alles wird gesucht! Registrieren Sie sich kostenlos auf unserer Homepage www.musiktandems.eu und finden Sie heute noch das Angebot, das Sie schon lange suchen. Wichtig: Sie können sich nur für das Musiktandem anmelden, wenn Sie selbst auch Unterricht anbieten können, also zum Beispiel ein Instrument spielen. Auf unserer Website finden Sie auch weitere Informationen zum Ablauf und können den Service kontaktieren.",
    "summary": "منصة «تانديم الموسيقي» تجمع بين الموسيقيين لتبادل الدروس التعليمية في العزف والغناء والتأليف الموسيقي مجانًا، بشرط أن يكون المشترك قادرًا بدوره على تدريس آلة أو مهارة موسيقية لغيره."
