    "summary": "يدعو مسرح الدمى \"Die Langohren\" العائلات يوم الأحد الساعة الثالثة عصرًا لمشاهدة العرض المسرحي \"هاتشي، آنا الصغيرة\" المناسب للكبار والأطفال من سن 6 سنوات فأكثر، مع توفر تذاكر محدودة متبقية للحجز عبر الهاتف."
