    "de": "Zusatz-Versicherung Liebe Leserin, lieber Leser, gepflegte Zähne hängen oft von der finanziellen Möglichkeiten des Patienten ab. Mit der Krankenkasse alleine kommt oft nicht weit. Mit der DENTAL VERSICHEUNG 100Plus von WarnstädtHyper verdoppeln Sie bei Zahnersatz den Zuschuss Ihrer gesetzlichen Krankenkasse. Keine Altersbegrenzung, günstige Monatsbeiträge. Nutzen Sie noch heute diese wichtigen Vorteile. Rufen sie an: 069-780086753 oder informieren Sie sich im Internet unter www.neue-zaehne.eu. Wir schicken Ihnen die Unterlagen zu.",
