    "de": "Gute Schuhe müssen nicht unbedingt teuer sein. Zu diesem Ergebnis kommt ein Test, der von einem deutschen Fernsehender durchgeführt wurde. Mehrere Schuh- und Modespezialisten sollten unter ähnlich aussehenden Modellen das jeweils am besten verarbeitete, das schönste und das teuerste Modell herausfinden. Dabei waren jeweils ein Designerschuhpaar, zwei Mittelklassemodelle und zwei Paar aus billigen Schuhketten. Im Ergebnis waren die Spezialisten oft nicht in der Lage, die Qualität zu unterscheiden. In einem Fall wurde sogar das billigste Modell für einen Designerschuh gehalten.",
    "summary": "يكشف اختبار أجرته قناة تلفزيونية ألمانية أن الأحذية الجيدة لا يشترط أن تكون باهظة الثمن، إذ عجز خبراء الأحذية والموضة في كثير من الأحيان عن التمييز بين الأحذية الفاخرة والمتوسطة والرخيصة من حيث الجودة."
