    "k": "B",
    "de": "Alte Jeans, Blusen oder Kleider hat jeder bei sich im Schrank. Ob das gute Stück zu eng ist, aus der Mode gekommen ist – werfen muss man es nicht. Aus alten Sachen lässt sich wunderbar Neues kreieren: vom Stuhlbzug bis zur trendigen Weste. Mit diesem Ratgeber nähen Anfänger Schritt für Schritt ihre neuen Accessoires aus alten Jeans ganz schnell zu einem neuen Schmuckstück. Autorin Amélie Betker widmet sich seit über fünfzehn Jahren Mode-Accessoires und teilt ihr Wissen und ihre Begeisterung fürs Nähen weiterzugeben. Amélie Betker: Aus alt mach neu! Kreative Nähprojekte für ausgediente Kleidungsstücke. Paperback, 144 Seiten, 14,99 €",
