    "summary": "يعرض المعرض الدائم \"طرق إلى الطبيعة\" في مركز زوار الحديقة الوطنية للغابة البافارية معلومات شاملة عن الغابة وأهميتها والكائنات التي تعيش فيها مع برنامج أفلام متنوع ودخول مجاني يوميًا."
