    "de": "Heiße Rhythmen und kühle Drinks Am Samstag, dem 3. August, erwartet Sie im Waldschwimmbad Hainichen bei Rock am Pool ein Feuerwerk aus Musik und Unterhaltung. Einlass zum Konzert ist ab 18:30 Uhr. Die Bands „Lion Poem“ und „Cosmos 1“ heizen den Besuchern ordentlich ein. Das Konzert endet um 0:30 Uhr. Bis 23 Uhr können die Besucher baden oder Beach-Volleyball spielen. Das Jugendzentrum Hainichen hat ein Programm für Jugendliche mit Lagerfeuer und Spielen vorbereitet. Für Essen und Getränke zu moderaten Preisen ist gesorgt. Die Eintrittspreise: Erwachsene 8€ Kinder und Jugendliche von 7 bis 14 Jahren 6€.",
    "summary": "حفل موسيقي مسائي في مسبح الغابة بهاينيشن يوم السبت 3 أغسطس ابتداءً من الساعة 18:30 حتى منتصف الليل، يتيح للزوار الاستمتاع بالموسيقى والسباحة ولعب كرة الطائرة الشاطئية حتى الساعة 23:00."
