    "de": "Aktion ”Sauberes Grün” Die Aktion “Sauberes grün” findet dieses Jahr nicht wie bisher an einem einzigen Tag statt, sondern dauert gleich drei Tage. Wir rufen Kindergärten, Schulen und Vereine dazu auf, sich auch dieses Jahr wieder zahlreich an unserer gemeinnützigen Putzaktion zu beteiligen. Ausgerüstet mit Handschuhen und Säcken, werden die Teilnehmerinnen und Teilnehmer Grünflächen, Parks und Spielplätze in der Stadt säubern. Auch Einzelpersonen sind herzlich willkommen! Am Samstag gibt es dann wieder das große Abschlussfest. Unsere jährliche Aktion für eine saubere Stadt, dieses Jahr vom 2. bis 4. Mai. Anmeldungen bei den städtischen Reinigungsbetrieben: 0240-191980.",
    "summary": "حملة تطوعية سنوية لمدة ثلاثة أيام من 2 إلى 4 مايو لتنظيف المساحات الخضراء والحدائق وملاعب الأطفال في المدينة بمشاركة المدارس والجمعيات والأفراد، وتختتم باحتفال يوم السبت."
