    "de": "Tag der offenen Tür in der städtischen Bücherei Zum Anlass des Welttags des Buches am 23 April möchten wir uns ganz den jungen Lesern widmen. Unser Kinderprogramm umfasst auch spannende Lesungen, für die wir noch Freiwillige unter achtzehn suchen. Nicht Lehrer oder Eltern, sondern junge Menschen sollen den ganz Kleinen aus alten und neuen Kinderbüchern vorlesen. Wenn du gerne (vor)liest, dann bist du am 23. April bei uns genau richtig! Schick uns einfach deine Daten und einen Lesevorschlag per Mail an: info@buecherei-stadt.com. Übrigens: Als kleine Belohnung darfst du dich bei unserem Bücher-Flohmarkt bedienen!",
    "summary": "يوم الأبواب المفتوحة في مكتبة المدينة بمناسبة اليوم العالمي للكتاب في 23 أبريل، مع البحث عن متطوعين دون الثامنة عشرة لقراءة القصص من كتب الأطفال للصغار."
