    "de": "The Bourne Identity Sonntag , 13. Januar Spielfilm , 130 Min . USA 2002 Irgendwo auf dem Mittelmeer treibt ein Fischerboot im Sturm . Nicht weit davon entfernt schwimmt ein Mann , der für tot gehalten wird . Einmal geborgen , entpuppt sich der vermeintlich Ertrunkene jedoch als lebendig , allerdings schwer verletzt . In nerhalb kurzer Zeit kommt er zwar wieder zu Kräften , allein seine Erinnerung an die Nacht , in der er ins Wasser fiel und in der ihm zweimal in den Rücken geschossen wurde , kehrt nicht zurück . Weil der einzige Hinweis auf die wahre Identität ein in den Oberschenkel implantierter Code für ein Schweizer Num mernkonto ist , begibt sich der Unbekannte auf direktem Weg nach Zürich . Dort stellt er fest , dass sein Name Jason Bourne ist , er in Paris wohnt und jede Menge Geld auf seinem Konto hat . Merkwürdig ist allerdings dass Jason auch noch weitere eigene Identitäten vorfindet , je weils komplettiert mit Reisepaſ , Führerschein und anderen Do kumenten . Jason beschließt , das Geld von seinem Konto mitzu nehmen und schleunigst wieder zu verschwinden . Allmählich dämmert ihm , dass er zwar einerseits als Agent im Staats dienst , andererseits aber auch als Auftragskiller tätig ....",
