    "de": ". Löwenalarm ! Jagd auf Menschenfresser Etwa 40.000 Löwen leben in Af rika , rund die Hälfte von ihnen in Tansania . Trotz dieser großen Zahl kommt es in der Regel nur vereinzelt zu Angriffen auf Men schen . In den ersten Jahren des 21. Jahr hunderts ist die Zahl der An griffsopfer jedoch sprunghaft angestiegen . Ein Team um den amerikanischen Löwenforscher Craig Parker sucht nach Ursa chen . Für Packer scheint es sich nicht um einzelne Löwen zu handeln , sondern um eine ganze Population . Um die Menschen besser schützen zu können und mehr über die Lebensweise der Löwen zu erfahren , versuchen Craig Packer und sein Team , ein zelne Raubkatzen mit GPS - Gerä ten auszustatten .",
