    "k": "D",
    "de": "Auf den Spuren des römischen Dichters Ausonius Von Bingen am Rhein bis nach Trier an der Mosel führt dieser nach dem römischen Dichter Ausonius benannte Wanderweg. Auf der ehemaligen römischen Heerstraße geht es stets über die Höhenrücken des Hunsrück. Durch Wälder und vorbei an Hunsrücker Dörfern ist die römische Vergangenheit an der Strecke und in Museen allgegenwärtig. Der 140 Kilometer lange Weg, den auch Ausonius bereiste, führt über die Höhen und durchschneidet die Bachtäler in stetigem Auf und Ab, um dann ab Neumagen die Mosel bis nach Trier zu begleiten.",
    "summary": "مسار المشي التاريخي «أوزونيوس» الممتد لمسافة 140 كيلومترًا من بينغن إلى تريير عبر الغابات والقرى، مع فرصة لاكتشاف الآثار والمتاحف الرومانية على طول الطريق."
