    "de": "Extra für Musicalfans MAMMA MIA! ist eine mitreißende Musical-Komödie mit den 22 größten Hits von ABBA - und keine langweilige Biografie. Alle Songs werden auf Deutsch gesungen, so ist ein schwungvoller und unterhaltsamer Abend garantiert. Die mitreißende Musical-Komödie von Benny Andersson und Björn Ulvaeus hat weltweit schon über 24 Millionen Zuschauer begeistert. MAMMA MIA! - ein grandiöses Stück über Liebe, Familie und Freundschaft. Vorstellungen jeden Abend um 18 und 20.30 Uhr. Hamburg Operettenhaus Hamburg Spielbudenplatz 1 D-20369 Hamburg",
    "summary": "عرض مسرحي غنائي كوميدي بعنوان «ماما ميا!» يقدم أشهر أغاني فرقة آبا مترجمة ومغناة بالألمانية كل مساء في مسرح الأوبريت بهامبورغ."
