    "de": "Bad Elster - heilendes Wasser aus sprudelnden Quellen In Bad Elster sprudeln gleich drei Trinkquellen unterschiedlicher Zusammensetzung und Heilwirkung. Das Herzstück einer Trink- und Badekur sind die Moritz- und die Marienquelle, die sich in der Nähe des Badeplatzes befinden. Bereits 1669 wurde den Quellen eine heilende Kraft bestätigt: Mineral- und Sprudelbäder beugen Herz- und Kreislauferkrankungen vor, Naturmoorbäder und Packungen helfen gegen Rheuma, Arthritis, bei Frauenleiden, dem Ausheilen von Sport- und Unfallverletzungen sowie bei der operative Nachsorge und Reha-Maßnahmen. Und Trinkkuren unterstützen die Heilung bei Stoffwechsel-, Nieren- und Harnwegserkrankungen.",
