    "de": "Die Geldschule :Sparen-Steuern-AltersvorsorgeNehmen Sie Ihre Finanzen selbst in die Hand: Ob Sie für hre Rente vorsorgen wollen oder einfach mehr sparen wollen- das neue Buch des Finanzexperten Kai Mueggenburg liefert Ihnen wertvolle Informationen. Es stellt Ihnen ein umfangreiches Basiswissen zum Thema Geld zur Verfügung Außerdem bekommen Sie Tipps, wie Sie Ihre eigene Spar und Investitionsstrategie erarbeiten können. Das Buch zeigt auf leicht verständliche Weise, wie man sein Geld einfach und gut anlegen kann Es enthält außerdem Checklisten, eine Liste mit wichtigen Adressen und ein umfangreiches Glossar,Taschenbuch, 14,80 €",
