    "de": "Sie lieben Filme? Dann machen Sie doch das Kino zu Ihrem Arbeitsplatz und werden Sie Teil unseres Teams! Das Metropolis Filmtheater Altenberg sucht eine Aushilfe als Urlaubsvertretung für die Monate Juli und August, 25 Stunden pro Woche. Zu Ihren Aufgaben gehören u. a. der Verkauf von Kinokarten, Popcorn und Getränken sowie die Einlasskontrolle und die Vorbereitung der Säle. Sie sind volljährig, zuverlässig und bereit, auch am Abend oder Wochenende zu arbeiten? Dann freuen wir uns auf Ihre Bewerbung mit kurzem Anschreiben und Lebenslauf per E-Mail. Metropolis Kino Altenberg info@metropolis-altenberg.ne",
    "summary": "إعلان عن وظيفة مؤقتة بدوام جزئي في دار سينما خلال شهري يوليو وأغسطس لبيع التذاكر والمأكولات ومراقبة الدخول."
